def quicksort(data : list) -> list:
    if len(data) <= 1:
        return data
    left = []
    middle = []
    right = []
    pivot = random.choice(data) # random pivot
    #pivot = data[len(data) // 2] # split in half
    for val in data:
        if val < pivot:
            left.append(val)
        if val == pivot:
            middle.append(val)
        if val > pivot:
            right.append(val)
    return quicksort(left) + middle + quicksort(right)

